	return ($Errors == 0);
}

function HighestFileName($Path_To_Root) {
	$files = glob($Path_To_Root . '/sql/updates/*.php');
	natsort($files);
	$LastFile = array_pop($files);
	return $LastFile ? basename($LastFile, ".php") : '';
}

